// Tests the TypeScript build against test-vectors/vectors.json (generated by the
// Python implementation) and, for numbers, against V8's own Number#toString.
import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import * as vcp from "../dist/index.js";

const here = fileURLToPath(new URL(".", import.meta.url));
const V = vcp.parseJson(readFileSync(here + "../../test-vectors/vectors.json", "utf8"));
const hex = vcp.toHex;
const unhex = vcp.fromHex;

function f64(bits) {
  const dv = new DataView(new ArrayBuffer(8));
  dv.setBigUint64(0, BigInt("0x" + bits));
  return dv.getFloat64(0);
}

test("number formatting matches V8 and the Python vectors", () => {
  assert.ok(V.numbers.length > 4000);
  for (const { bits, es } of V.numbers) {
    const x = f64(bits);
    assert.equal(vcp.formatNumber(x, { strict: true }), es, bits);
    assert.equal(Object.is(x, -0) ? "0" : String(x), es, bits);
    const ambiguous = Number.isInteger(x) && Math.abs(x) >= 2 ** 53 && Math.abs(x) < 1e21;
    if (ambiguous) assert.throws(() => vcp.formatNumber(x), vcp.CanonicalizationError);
    else assert.equal(vcp.formatNumber(x), es, bits);
  }
});

test("JCS vectors", () => {
  for (const { input, canonical } of V.jcs) {
    assert.equal(vcp.canonicalizeString(vcp.parseJson(input)), canonical, input);
  }
  for (const v of V.integers) {
    const b = BigInt(v.value);
    assert.equal(vcp.formatNumber(b), v.default, v.value);
    if (v.strict === null) assert.throws(() => vcp.formatNumber(b, { strict: true }), vcp.CanonicalizationError, v.value);
    else {
      assert.equal(vcp.formatNumber(b, { strict: true }), v.strict, v.value);
      assert.equal(String(Number(b)), v.strict, v.value); // V8 is the RFC 8785 reference for strict mode
    }
  }
  assert.notEqual(vcp.formatNumber(1791504000123456768n), vcp.formatNumber(1791504000123456800n));
  assert.throws(() => vcp.formatNumber(1.8e18), vcp.CanonicalizationError);
  assert.throws(() => vcp.canonicalizeString("\ud800"), vcp.CanonicalizationError);
  assert.throws(() => vcp.canonicalizeString(NaN), vcp.CanonicalizationError);
});

test("strict JSON parsing", () => {
  assert.throws(() => vcp.parseJson('{"a":1,"a":2}'), vcp.StrictJSONError);
  assert.throws(() => vcp.parseJson("{\"a\":NaN}"), vcp.StrictJSONError);
  assert.throws(() => vcp.parseJson("﻿{}"), vcp.StrictJSONError);
  assert.throws(() => vcp.parseJson(new Uint8Array([0xef, 0xbb, 0xbf, 0x7b, 0x7d])), vcp.StrictJSONError);
  assert.equal(vcp.parseJson("1791504000123456789"), 1791504000123456789n);
  assert.equal(vcp.parseJson("9007199254740991"), 9007199254740991);
  const o = vcp.parseJson('{"__proto__": {"x": 1}}');
  assert.deepEqual(Object.keys(o), ["__proto__"]);
  assert.equal(Object.getPrototypeOf(o), Object.prototype);
});

test("Merkle vectors", () => {
  const leaves = V.merkle.leaves.map(unhex);
  for (const [n, root] of Object.entries(V.merkle.roots)) {
    assert.equal(hex(vcp.merkleRoot(leaves.slice(0, +n))), root, `root ${n}`);
  }
  for (let n = 1; n <= 24; n++) {
    const ls = leaves.slice(0, n);
    const t = new vcp.MerkleTree(ls);
    assert.equal(hex(vcp.legacyExampleRoot(ls)), V.merkle.legacy_example_roots[n]);
    for (let i = 0; i < n; i++) {
      const p = t.inclusionProof(i);
      assert.deepEqual(p.map(hex), V.merkle.inclusion[n][i]);
      assert.ok(vcp.verifyInclusion(ls[i], i, n, p, t.root));
      assert.ok(!vcp.verifyInclusion(ls[i], n, n, p, t.root));
      if (n > 1) assert.ok(!vcp.verifyInclusion(ls[i], (i + 1) % n, n, p, t.root));
      if (p.length) {
        const bad = p.map((x) => new Uint8Array(x));
        bad[0][0] ^= 1;
        assert.ok(!vcp.verifyInclusion(ls[i], i, n, bad, t.root));
        assert.ok(!vcp.verifyInclusion(ls[i], i, n, p.slice(1), t.root));
      }
    }
    for (let m = 1; m < n; m++) {
      const p = t.consistencyProof(m);
      assert.deepEqual(p.map(hex), V.merkle.consistency[n][m]);
      const small = vcp.merkleRoot(ls.slice(0, m));
      assert.ok(vcp.verifyConsistency(m, n, small, t.root, p));
      assert.ok(!vcp.verifyConsistency(m, n, t.root, t.root, p));
      assert.ok(!vcp.verifyConsistency(m, n, small, t.root, p.slice(0, -1)));
    }
    assert.ok(vcp.verifyConsistency(n, n, t.root, t.root, []));
    assert.ok(vcp.verifyConsistency(0, n, new Uint8Array(32), t.root, []));
  }
});

test("Ed25519 RFC 8032 vectors", () => {
  for (const v of V.ed25519_rfc8032) {
    const k = new vcp.SigningKey(v.seed);
    assert.equal(hex(k.verifyKey.raw), v.public);
    assert.equal(hex(k.sign(unhex(v.message))), v.signature);
    assert.ok(k.verifyKey.verify(unhex(v.signature), unhex(v.message)));
  }
  assert.deepEqual(vcp.fromBase64("YQ=="), new Uint8Array([0x61]));
  assert.equal(vcp.fromBase64("YR=="), null); // non-canonical padding bits
});

test("Ed25519 edge cases: small-order and non-canonical keys, mixed-order R, S + L", () => {
  const E = V.ed25519_edges;
  for (const k of [...E.small_order_public_keys, ...E.non_canonical_public_keys, ...E.torsion_component_public_keys]) {
    assert.throws(() => new vcp.VerifyKey(k), vcp.KeyRejected, k);
  }
  assert.throws(() => new vcp.VerifyKey(E.identity_forgery.public), vcp.KeyRejected);
  const key = new vcp.SigningKey(V.signing_key_seed_hex).verifyKey;
  const h = V.events[0].event_hash;
  assert.ok(vcp.verifyEventSignature(h, V.events[0].event.Security.Signature, key));
  assert.ok(!vcp.verifyEventSignature(h, E.event0_mixed_order_signature, key));
  assert.ok(!vcp.verifyEventSignature(h, E.event0_s_plus_l_signature, key));
});

test("toJson and parseJson keep TimestampInt exactly", () => {
  const key = new vcp.SigningKey(V.signing_key_seed_hex);
  const p = new vcp.Producer(key, "a", "c", "org.example:p", { precision: "NANOSECOND" });
  const ev = p.create("INIT", { "VCP-GOV": { AlgoID: "x" } }, { timestampNs: 1791504000123456768n });
  const back = vcp.parseJson(vcp.toJson(ev));
  assert.equal(back.Header.TimestampInt, 1791504000123456768n);
  assert.equal(vcp.verifyEvent(back, key.verifyKey).status, vcp.VALID);
});

test("events reproduce byte for byte", () => {
  const key = new vcp.SigningKey(V.signing_key_seed_hex);
  assert.equal(key.verifyKey.toBase64(), V.public_key_base64);
  for (const row of V.events) {
    const ev = row.event;
    assert.equal(vcp.canonicalizeString(ev.Header), row.canonical_header);
    assert.equal(vcp.canonicalizeString(ev.Payload), row.canonical_payload);
    const h = vcp.computeEventHash(ev.Header, ev.Payload, { prevHash: ev.Security.PrevHash ?? null });
    assert.equal(h, row.event_hash);
    const sealed = vcp.sealEvent(ev.Header, ev.Payload, key, { prevHash: ev.Security.PrevHash ?? null });
    assert.equal(sealed.Security.Signature, ev.Security.Signature);
    assert.equal(sealed.Security.EventHash, ev.Security.EventHash);
  }
  const batch = vcp.buildBatch(V.events.map((r) => {
    const e = structuredClone(r.event);
    for (const k of ["MerkleRoot", "MerkleIndex", "AnchorReference"]) delete e.Security[k];
    return e;
  }));
  assert.equal(batch.merkleRoot, V.batch.merkle_root);
  for (const [i, p] of Object.entries(V.batch.inclusion_proofs)) assert.deepEqual(batch.inclusionProof(+i), p);
  assert.equal(vcp.signMerkleRoot(batch.merkleRoot, key), V.batch.anchor_record.Signature);
  assert.equal(vcp.verifyEvent(V.events[0].event, key.verifyKey).status, V.single_event_status);
});

test("verification cases match the Python verifier", () => {
  for (const c of V.cases) {
    let rep;
    if (c.kind === "chain") rep = vcp.verifyChain(c.events);
    else {
      const ext = c.external_anchor_result;
      rep = vcp.verifyBatch(c.events, c.anchor_record, {
        publicKey: c.public_key,
        externalAnchorVerifier: ext === null ? null : () => ext,
      });
    }
    assert.equal(rep.status, c.expected_status, c.name);
    const got = [...new Set(rep.checks.filter((x) => x.status !== "VALID").map((x) => JSON.stringify([x.name, x.status, x.reason ?? ""])))]
      .sort()
      .map((s) => JSON.parse(s));
    assert.deepEqual(got, c.expected_non_valid, c.name);
    assert.deepEqual(rep.checks.map((x) => [x.name, x.status, x.reason ?? "", x.subject ?? ""]), c.expected_checks, c.name);
  }
});

test("producer round trip and three values", () => {
  const key = new vcp.SigningKey(V.signing_key_seed_hex);
  const p = new vcp.Producer(key, "ts-actor", "c1", "org.example:ts", { precision: "NANOSECOND", usePrevHash: true });
  for (let i = 0; i < 7; i++) p.create(i ? "ORD" : "INIT", { "VCP-TRADE": { Price: `1.${i}` } }, { timestampNs: 1791504000000123456n + BigInt(i) * 777n });
  const { batch, record } = p.closeBatch({ anchorTarget: { Type: "TSA", Identifier: "tsa.example", Proof: "x" } });
  assert.equal(vcp.verifyBatch(batch.events, record, { publicKey: key.verifyKey, externalAnchorVerifier: () => true }).status, vcp.VALID);
  assert.equal(vcp.verifyBatch(batch.events, record, { publicKey: key.verifyKey }).status, vcp.INDETERMINATE);
  assert.equal(vcp.verifyChain(batch.events).status, vcp.VALID);
  const json = batch.events.map((e) => vcp.toJson(e)).join("\n");
  const back = vcp.parseJsonLines(json);
  assert.equal(vcp.verifyBatch(back, record, { publicKey: key.verifyKey, externalAnchorVerifier: () => true }).status, vcp.VALID);
  for (let i = 0; i < 7; i++) {
    const r = vcp.verifyInclusionProof(batch.events[i].Security.EventHash, i, 7, batch.inclusionProof(i), batch.merkleRoot, true);
    assert.equal(r.status, vcp.VALID);
  }
  assert.equal(vcp.isoFromNs(1791504000123456789n, "NANOSECOND"), "2026-10-09T00:00:00.123456789Z");
  assert.deepEqual(vcp.nsFromIso("2026-10-09T09:00:00.5+09:00"), [1791504000500000000n, 1]);
  assert.equal(vcp.uuid7(0x0123456789ab, new Uint8Array(10)), "01234567-89ab-7000-8000-000000000000");
});
